import sys
import json
import os

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    awards_file = os.path.join(packet_dir, 'usaspending_awards.json')

    data = {}
    if os.path.exists(awards_file):
        with open(awards_file, 'r') as f:
            awards = json.load(f)
            for award in awards:
                entity_id = award.get("generated_unique_award_id")
                if not entity_id:
                    continue
                if entity_id not in data:
                    data[entity_id] = {
                        "performance start": set(),
                        "performance end": set(),
                        "amount obligated": set(),
                        "potential value": set()
                    }

                pop = award.get("period_of_performance")
                if isinstance(pop, dict):
                    start_date = pop.get("start_date")
                    if start_date is not None:
                        data[entity_id]["performance start"].add((str(start_date), "usaspending_awards"))

                    end_date = pop.get("end_date")
                    if end_date is not None:
                        data[entity_id]["performance end"].add((str(end_date), "usaspending_awards"))

                total_obligation = award.get("total_obligation")
                if total_obligation is not None:
                    data[entity_id]["amount obligated"].add((str(total_obligation), "usaspending_awards"))

                base_and_all_options = award.get("base_and_all_options")
                if base_and_all_options is not None:
                    data[entity_id]["potential value"].add((str(base_and_all_options), "usaspending_awards"))

    results = {}
    for pair in manifest.get("pairs", []):
        rule_id, entity_id = pair.split("::")
        facts = manifest.get("facts", {}).get(rule_id, [])

        pair_result = {}
        for fact in facts:
            if entity_id not in data or fact not in data[entity_id]:
                pair_result[fact] = "ABSENT"
            else:
                values = data[entity_id][fact]
                if len(values) == 0:
                    pair_result[fact] = "ABSENT"
                elif len(values) == 1:
                    pair_result[fact] = list(list(values)[0])
                else:
                    pair_result[fact] = "CONFLICT"

        results[pair] = pair_result

    print(json.dumps(results, indent=2))

if __name__ == "__main__":
    main()

