import sys
import json
import os

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    awards_path = os.path.join(packet_dir, 'usaspending_awards.json')
    awards_data = []
    if os.path.exists(awards_path):
        with open(awards_path, 'r') as f:
            awards_data = json.load(f)

    awards_by_id = {}
    for award in awards_data:
        award_id = award.get('generated_unique_award_id')
        if award_id:
            if award_id not in awards_by_id:
                awards_by_id[award_id] = []
            awards_by_id[award_id].append(award)

    results = {}

    for pair in manifest.get('pairs', []):
        rule_id, entity = pair.split('::', 1)
        facts = manifest.get('facts', {}).get(rule_id, [])

        pair_result = {}
        records = awards_by_id.get(entity, [])

        for fact in facts:
            values = set()
            doc_name = "usaspending_awards"

            for record in records:
                val = None
                if rule_id == "usa.period_3y":
                    pop = record.get("period_of_performance") or {}
                    if fact == "performance start":
                        val = pop.get("start_date")
                    elif fact == "performance end":
                        val = pop.get("end_date")

                    if val is not None:
                        val = str(val).split("T")[0].split(" ")[0]

                elif rule_id == "usa.obligated_95":
                    if fact == "amount obligated":
                        val = record.get("total_obligation")
                    elif fact == "potential value":
                        val = record.get("base_and_all_options")

                    if val is not None:
                        val = str(val)

                if val is not None:
                    values.add(val)

            if len(values) == 0:
                pair_result[fact] = "ABSENT"
            elif len(values) == 1:
                pair_result[fact] = [list(values)[0], doc_name]
            else:
                pair_result[fact] = "CONFLICT"

        results[pair] = pair_result

    print(json.dumps(results, indent=2))

if __name__ == "__main__":
    main()

